-- The login banner and the minimap tooltip.
L["Click to open the settings"] = "Clicca per aprire le impostazioni";
L["Circular class, spec and role icons on every nameplate, live crowd-control icons and instant Healer CC alerts."] = "Icone rotonde di classe, specializzazione e ruolo su ogni targhetta, icone di controllo in tempo reale e avvisi istantanei di controllo sul guaritore.";
L["OPlates only adds icons. Your nameplate addon keeps its own bars and style."] = "OPlates aggiunge solo icone. Il tuo addon delle targhette mantiene le sue barre e il suo stile.";
L["Type %s or click the minimap button to open the settings."] = "Digita %s o clicca il pulsante della minimappa per aprire le impostazioni.";
L["Open settings"] = "Apri impostazioni";
L["Test"] = "Prova";
L["Hide"] = "Nascondi";

-- The settings window.
L["|cffff3b3bWARMANE AND OTHER SERVERS THAT FORBID CLIENT MODIFICATIONS ARE NOT COMPATIBLE WITH awesome_wotlk OR ANY CLIENT PATCH. DO NOT INSTALL IT THERE.|r"] = "|cffff3b3bWARMANE E GLI ALTRI SERVER CHE VIETANO LE MODIFICHE AL CLIENT NON SONO COMPATIBILI CON awesome_wotlk NÉ CON ALCUNA PATCH DEL CLIENT. NON INSTALLARLA LÌ.|r";
L["Your client is unpatched, so players reveal their class only after you mouseover them. The free FreakySphere awesome_wotlk client patch gives every visible player class colors, icons and borders instantly, with no mouseover at all. Copy the link below if you want it. OPlates runs fine without it."] = "Il tuo client non è patchato, quindi i giocatori rivelano la loro classe solo quando ci passi sopra il mouse. La patch client gratuita awesome_wotlk di FreakySphere dà a ogni giocatore visibile colori di classe, icone e bordi all'istante, senza alcun passaggio del mouse. Copia il link qui sotto se la vuoi. OPlates funziona benissimo senza.";
L["OPlates now reads nameplate units straight from your client: every visible player gets class colors, icons and borders instantly, no mouseover needed. You can switch this off in /op > Advanced."] = "OPlates ora legge le unità delle targhette direttamente dal tuo client: ogni giocatore visibile riceve subito colori di classe, icone e bordi, senza passaggio del mouse. Puoi disattivarlo in /op > Avanzate.";
L["Your client has the awesome_wotlk patch, but OPlates is not using its nameplate units, so you are missing instant class colors, icons and borders on every visible player. Turn it on now?"] = "Il tuo client ha la patch awesome_wotlk, ma OPlates non usa le sue unità delle targhette, quindi ti mancano colori di classe, icone e bordi istantanei su ogni giocatore visibile. Attivarla ora?";
L["|cffff3b3bWarmane: patch not allowed|r"] = "|cffff3b3bWarmane: patch non consentita|r";
