L["awesome_wotlk patch: "] = "Patch awesome_wotlk: ";
L["Nameplate units: "] = "Unità delle targhette: ";
L["off"] = "disattivato";
L["Everything"] = "Tutto";
L["Healers only"] = "Solo guaritori";
L["Tanks only"] = "Solo tank";
L["Class icons only"] = "Solo icone di classe";
L["Spec icons only"] = "Solo icone di specializzazione";
L["Pets only"] = "Solo famigli";
L["Flag carriers only"] = "Solo portatori di bandiera";
L["Crowd control only"] = "Solo controllo";
L["Buffs only"] = "Solo buff";
L["Debuffs only"] = "Solo debuff";
L["Pick which icons may appear. \"Crowd control only\" shows CC icons only (gone the moment the CC ends). \"Buffs only\" / \"Debuffs only\" show your listed spells (plus CC when \"Show crowd control\" is on). Options a mode doesn't use turn grey and keep their values."] = "Scegli quali icone possono apparire. \"Solo controllo\" mostra solo icone CC (spariscono appena il CC finisce). \"Solo buff\" / \"Solo debuff\" mostrano gli incantesimi elencati (più il CC quando \"Mostra controllo\" è attivo). Le opzioni che un modo non usa diventano grigie e mantengono i loro valori.";
L["Seconds left, in the center of CC and aura icons. White from 1 minute, yellow under 1 minute, red from 5 seconds (then tenths). Only for effects with a known duration."] = "Secondi rimanenti, al centro delle icone CC e aura. Bianco da 1 minuto, giallo sotto 1 minuto, rosso da 5 secondi (poi decimi). Solo per effetti con durata nota.";
L["Class Filters"] = "Filtri di classe";
L["Spec Filters"] = "Filtri di specializzazione";
L["Choose which classes show their class icon. A hidden class still shows its spec, healer/tank, CC and aura icons."] = "Scegli quali classi mostrano la loro icona di classe. Una classe nascosta mostra comunque specializzazione, guaritore/tank, CC e icone aura.";
L["Choose which specs show their spec icon. A hidden spec shows the class icon instead (when class icons are on and that class is not hidden)."] = "Scegli quali specializzazioni mostrano la loro icona. Una specializzazione nascosta mostra invece l'icona di classe (quando le icone di classe sono attive e quella classe non è nascosta).";
